begin;
create or replace function public.public_ready_stock_availability_v1(p_variant_size_ids uuid[]) returns table(variant_size_id uuid,available integer) language sql stable security definer set search_path='' as $function$
select balance.variant_size_id,coalesce(sum(balance.on_hand_quantity-balance.reserved_quantity),0)::integer from public.inventory_balances balance join public.inventory_locations location on location.id=balance.location_id join public.product_variant_sizes variant_size on variant_size.id=balance.variant_size_id join public.product_variants variant on variant.id=variant_size.variant_id join public.products product on product.id=variant.product_id where balance.variant_size_id=any(coalesce(p_variant_size_ids,array[]::uuid[])) and cardinality(coalesce(p_variant_size_ids,array[]::uuid[])) between 1 and 100 and location.active and location.location_type<>'legacy' and variant_size.status='active' and variant_size.is_active and variant.status='active' and variant.is_active and product.status='active' and product.status_aktif and product.sales_mode in('ready_stock','both') group by balance.variant_size_id
$function$;
revoke all on function public.public_ready_stock_availability_v1(uuid[]) from public;
grant execute on function public.public_ready_stock_availability_v1(uuid[]) to anon,authenticated,service_role;
insert into public.system_audit_log(entity_type,action,actor_role,source,reason,metadata) values('inventory_policy','public_canonical_inventory_availability_v1_applied','system','migration','Public product reads can access only aggregate canonical availability; location and movement details remain protected.',jsonb_build_object('exposed_fields',jsonb_build_array('variant_size_id','available'),'rls_disabled',false,'service_role_in_client',false));
commit;;
